{
  "name": "Cytomat 自动化微板培养箱/存储系统",
  "name_en": "Cytomat Automated Microplate Incubator/Storage System",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "Cytomat 是面向实验室自动化的微孔板培养与存储设备，提供温度、CO2、O2 与湿度等环境控制，配有内部摇床、条码读取与对接传送口。设备可在存储位、等待位、传送位及外部曝光位之间自动搬运微板，支持门控与铲式传送机构操作，适用于细胞培养、微生物培养及高通量筛选中的板级培养与中转存储。",
  "description_en": "Cytomat is an automated microplate incubator and storage system providing controlled temperature, CO2, O2, and humidity. It integrates internal shakers, barcode reading, and a robotic transfer station, moving plates between storage, wait, transfer, and exposed (external) positions with door control and a shovel-type transport mechanism. It is used for cell culture, microbial culture, and high-throughput screening for plate incubation and intermediate storage.",
  "actions": [
    {
      "action_name": "auto-action_exposed_to_storage",
      "description": "从设备外的曝光位取回微板，存入指定存储位，然后回到等待位并关门。",
      "description_en": "Return a plate from the exposed (external) position to the specified storage site, move back to wait, and close the door."
    },
    {
      "action_name": "auto-action_exposed_to_wait",
      "description": "从曝光位回到等待位并关闭门。",
      "description_en": "Move from the exposed position back to the wait position and close the door."
    },
    {
      "action_name": "auto-action_read_barcode",
      "description": "读取指定存储位置的条码信息。",
      "description_en": "Read the barcodes of the specified storage locations."
    },
    {
      "action_name": "auto-action_storage_to_exposed",
      "description": "从存储位取出微板，运送至设备外部的曝光位。",
      "description_en": "Retrieve a plate from storage and transport it to the exposed (external) position."
    },
    {
      "action_name": "auto-action_storage_to_transfer",
      "description": "从存储位取板，开门并将其移至传送口（transfer station），随后关门。",
      "description_en": "Retrieve a plate from storage, open the door, move it to the transfer station, then close the door."
    },
    {
      "action_name": "auto-action_storage_to_wait",
      "description": "从存储位取板并移动到等待位。",
      "description_en": "Retrieve a plate from storage and move it to the wait position."
    },
    {
      "action_name": "auto-action_transfer_to_storage",
      "description": "开门，从传送口取板，关门并将其放入指定存储位。",
      "description_en": "Open the door, retrieve a plate from the transfer station, close the door, and place it into the specified storage site."
    },
    {
      "action_name": "auto-action_transfer_to_wait",
      "description": "开门，从传送口取板，返回等待位并关闭门。",
      "description_en": "Open the door, retrieve a plate from the transfer station, return to the wait position, and close the door."
    },
    {
      "action_name": "auto-action_wait_to_exposed",
      "description": "从等待位将微板送至设备外的曝光位。",
      "description_en": "Move a plate from the wait position to the exposed (external) position."
    },
    {
      "action_name": "auto-action_wait_to_storage",
      "description": "从等待位将微板送入并卸载到指定存储位。",
      "description_en": "Move a plate from the wait position to the specified storage site and unload."
    },
    {
      "action_name": "auto-action_wait_to_transfer",
      "description": "从等待位将微板放至传送口，随后关闭门。",
      "description_en": "Place a plate from the wait position onto the transfer station and then close the door."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭培养箱/传送口的门。",
      "description_en": "Close the incubator/transfer door."
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将指定微板取出并送至外部装载托盘。",
      "description_en": "Fetch the specified plate to the external loading tray."
    },
    {
      "action_name": "auto-init_shakers",
      "description": "初始化内部摇床模块。",
      "description_en": "Initialize the internal shaker modules."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备（复位与回零），使系统进入可用状态。",
      "description_en": "Initialize the system (reset and home) to make it ready for operation."
    },
    {
      "action_name": "auto-open_door",
