      "description_en": "Retract the shovel-type transfer mechanism."
    },
    {
      "action_name": "auto-start_shaking",
      "description": "按设定频率启动摇床振荡（可选目标摇床）。",
      "description_en": "Start shaker oscillation at the specified frequency (optional shaker selection)."
    },
    {
      "action_name": "auto-stop",
