      "description_en": "Stop current operations and bring the device to an idle state."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止摇床振荡。",
      "description_en": "Stop shaker oscillation."
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "从装载托盘取入指定微板并存入指定存储位。",
      "description_en": "Take in the specified plate from the loading tray and store it at the specified site."
    },
    {
      "action_name": "auto-wait_for_task_completion",
      "description": "等待当前任务完成（忙标志清除），超时则报错。",
      "description_en": "Wait for the current task to complete (busy cleared), raising a timeout if it takes too long."
    },
    {
      "action_name": "auto-wait_for_transfer_station",
      "description": "等待传送口达到指定占用状态（占用/空闲）。",
      "description_en": "Wait for the transfer station to reach the desired occupancy state (occupied/unoccupied)."
    },
    {
      "action_name": "auto-get_overview_register",
      "description": "获取概览状态寄存器。",
      "description_en": "Get the overview status register."
    },
    {
      "action_name": "auto-get_warning_register",
